procedure @@proc@@(p_id in number) is
  l_note varchar2(200) := 'never write when others then raise; in prose';
begin
  /* touch the row */ update @@tab@@ set @@col@@ = l_note where id = p_id;
  @@proc2@@(p_id); /* exception
  when others then raise; */
exception
  when /* any failure */ others /* swallowed */ then -- @expect
    -- logger.log_error(sqlerrm);
    null;
end @@proc@@;

procedure @@proc@@(p_id in number) is
  procedure flush_row(p_row in number) is
  begin
    update @@tab@@
       set @@col@@ = sysdate
     where id = p_row;
  exception
    when others then -- @expect
      null;
  end flush_row;
begin
  flush_row(p_id);
  @@proc2@@(p_id);
exception
  when others then
    raise;
end @@proc@@;

function @@proc@@(p_id in number) return number is
  l_res number := 0;
begin
  <<outer>>
  begin
    declare
      l_tmp number;
    begin
      begin
        l_tmp := @@proc2@@(p_id);
        l_res := l_res + l_tmp;
      exception
        when others then -- @expect
          return -1;
      end;
    end;
  end outer;
  return l_res;
end @@proc@@;

procedure @@proc@@(p_id in number, p_status out varchar2) is
  c_hint constant varchar2(60) := q'[when others then raise; -- not here]';
  procedure step_one(p_n in number) is
  begin
    @@proc2@@(p_n);
  exception
    when others then
      raise;
  end step_one;
begin
  step_one(p_id);
  p_status := 'ok';
exception
  when others then -- @expect
    p_status := case when p_id > 0 then 'e_pos' else 'e_neg' end;
end @@proc@@;

procedure @@proc@@(p_id in number) is
	l_ok boolean := true;
begin
	@@proc2@@(p_id);
exception
	WHEN OTHERS -- @expect
	THEN
		l_ok := false;
		$IF $$verbose $THEN
		dbms_output.put_line('step failed');
		$ELSE
		null;
		$END
end @@proc@@;

negatives.code:
procedure @@proc@@(p_id in number) is
  l_txt varchar2(100) := 'when others then null;';
begin
  @@proc2@@(p_id);
  /* an earlier version had:
     exception
       when others then null;
  */
  dbms_output.put_line(l_txt);
exception
  -- when others then null;   (removed on purpose)
  when too_many_rows then
    null;
end @@proc@@;

function @@proc@@(p_id in number) return number is
  l_n number;
  function helper(p_x in number) return number is
  begin
    return p_x + 1;
  end helper;
begin
  <<outer>>
  begin
    l_n := helper(p_id);
  exception
    when no_data_found then
      l_n := 0;
  end outer;
  return l_n;
exception
  when others then
    rollback;
    raise /* propagate to the caller */ ;
end @@proc@@;

procedure @@proc@@(p_ids in dbms_sql.number_table) is
  l_fail number := 0;
begin
  for i in 1 .. p_ids.count loop
    continue when p_ids(i) is null;
    begin
      @@proc2@@(p_ids(i));
    exception
      when others then
        pkg_util.audit_trail.add(p_ids(i), 'null;');
        l_fail := l_fail + 1;
    end;
  end loop;
  dbms_output.put_line(l_fail);
end @@proc@@;

procedure @@proc@@(p_id in number, p_trace out varchar2) is
  "Last Id" number := p_id;
begin
  p_trace := null;
  @@proc2@@("Last Id");
exception
  when others then
    /* keep the backtrace for the caller */
    p_trace := dbms_utility.format_error_backtrace;
end @@proc@@;

procedure @@proc@@(p_id in number, p_code out number) is
begin
  p_code := 0;
  begin
    @@proc2@@(p_id);
  exception
    when value_error then
      null;
    when others then
      raise;
  end;
  @@proc2@@(p_id + 1);
exception
  WHEN OTHERS THEN
    p_code := SQLCODE;
end @@proc@@;
